<script>
    document.addEventListener('DOMContentLoaded', function() {
        // Force CTA section visibility
        const ctaSection = document.querySelector('.cta-section');
        if (ctaSection) {
            ctaSection.style.cssText = "background: linear-gradient(to right, #2196f3, #45f3ff) !important; padding: 80px 0 !important; position: relative !important; z-index: 100 !important; display: block !important; visibility: visible !important; opacity: 1 !important; border-top: 3px solid #fff; border-bottom: 3px solid #fff;";
        }
        
        // Initialize Typed.js
        if (document.getElementById('typed-text')) {
            new Typed('#typed-text', {
                strings: [
                    'Expert senior care services with compassion and dignity',
                    'Professional caregivers available 24/7 for personalized care',
                    'Creating a safe and supportive environment for senior citizens'
                ],
                typeSpeed: 50,
                backSpeed: 30,
                backDelay: 2000,
                loop: true,
                showCursor: true,
                cursorChar: '|'
            });
        }
        
        // Add scroll event for navbar
        window.addEventListener('scroll', function() {
            const navbar = document.querySelector('.navbar');
            if (window.scrollY > 50) {
                navbar.classList.add('scrolled');
            } else {
                navbar.classList.remove('scrolled');
            }
        });
        
        // Smooth scrolling for anchor links
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = this.getAttribute('href');
                if (targetId !== '#') {
                    const targetElement = document.querySelector(targetId);
                    if (targetElement) {
                        window.scrollTo({
                            top: targetElement.offsetTop - 80,
                            behavior: 'smooth'
                        });
                    }
                }
            });
        });
    });
</script>

