        width: 500px;
        height: 500px;
        top: -250px;
        right: -100px;
        animation: float 15s ease-in-out infinite;
    }
    
    .shape-2 {
        width: 300px;
        height: 300px;
        bottom: -150px;
        left: -150px;
        animation: float 20s ease-in-out infinite reverse;
    }
    
    .shape-3 {
        width: 200px;
        height: 200px;
        top: 40%;
        right: 15%;
        animation: float 25s ease-in-out infinite 5s;
    }
    
    .shape-4 {
        width: 350px;
        height: 350px;
        bottom: 15%;
        right: -100px;
        animation: float 18s ease-in-out infinite 3s;
    }
    
    .shape-5 {
        width: 250px;
        height: 250px;
        top: 20%;
        left: 10%;
        animation: float 22s ease-in-out infinite 7s;
    }
    
    @keyframes float {
        0% {
            transform: translate(0, 0) rotate(0deg);
        }
        25% {
            transform: translate(15px, 15px) rotate(5deg);
        }
        50% {
            transform: translate(0, 30px) rotate(0deg);
        }
        75% {
            transform: translate(-15px, 15px) rotate(-5deg);
        }
        100% {
            transform: translate(0, 0) rotate(0deg);
        }
    }
    
    /* Scroll Indicator */
    .scroll-indicator {
        position: absolute;
        bottom: 30px;
        left: 50%;
        transform: translateX(-50%);
        z-index: 10;
            display: flex;
        flex-direction: column;
            align-items: center;
        animation: fadeInUp 2s ease 1s forwards;
        opacity: 0;
    }
    
    .mouse {
        width: 30px;
        height: 50px;
        border: 2px solid rgba(255, 255, 255, 0.8);
        border-radius: 20px;
        position: relative;
        margin-bottom: 10px;
    }
    
    .wheel {
        width: 4px;
        height: 10px;
        background: #fff;
        position: absolute;
        top: 7px;
        left: 50%;
        transform: translateX(-50%);
        border-radius: 4px;
        animation: scroll 2s ease infinite;
    }
    
    @keyframes scroll {
        0% {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
        }
        100% {
            opacity: 0;
            transform: translateX(-50%) translateY(20px);
        }
    }
    
    .scroll-text {
        color: rgba(255, 255, 255, 0.8);
        font-size: 12px;
        letter-spacing: 2px;
        text-transform: uppercase;
    }
    
    /* Media Queries for Better Responsiveness */
    @media (max-width: 992px) {
        .brand-name {
            font-size: 4rem;
        }
        
        .hero-section {
            padding-top: 100px;
        }
        
        .navbar-collapse {
            background: rgba(13, 19, 33, 0.95);
            padding: 20px;
            border-radius: 10px;
            margin-top: 15px;
        }
    }
    
    @media (max-width: 768px) {
        .brand-name {
            font-size: 3.5rem;
        }
        
        .btn-group-hero {
            flex-direction: column;
            width: 80%;
            margin: 30px auto 0;
        }
        
        .hero-section {
            text-align: center;
            padding-top: 80px;
        }
        
        .hero-subtitle {
            font-size: 1.1rem;
            padding: 0 20px;
        }
    }
    
    @media (max-width: 576px) {
        .brand-name {
            font-size: 2.8rem;
            letter-spacing: 3px;
        }
        
        .site-logo {
            height: 60px;
        }
        
        .btn-group-hero .btn {
            width: 100%;
            margin: 0;
        }
    }

    /* New fixes specific to this issue */
    body {
        padding-top: 0 !important;
        margin-top: 0 !important;
    }
    
    .container-fluid {
        margin-top: 0 !important;
    }
    
    .brand-logo {
        margin-top: 60px; /* Adjust based on navbar height */
    }

    /* Modern Visual Effects and Elements */
    
    /* Neon Glow for Key Elements */
    .neon-glow {
        box-shadow: 0 0 10px rgba(69, 243, 255, 0.5),
                    0 0 20px rgba(69, 243, 255, 0.3),
                    0 0 30px rgba(69, 243, 255, 0.1);
    }
    
    /* Modern Card Hover Effects */
    .card {
        transition: all 0.5s cubic-bezier(0.23, 1, 0.32, 1);
        transform-style: preserve-3d;
        perspective: 1000px;
    }
    
    .card:hover {
        transform: translateY(-10px) rotateX(5deg);
    }
    
    .card:hover .service-icon {
        transform: translateZ(20px) rotate(360deg);
        transition: all 0.8s cubic-bezier(0.23, 1, 0.32, 1);
    }
    
    /* Liquid Button Effect */
    .btn-glass {
        position: relative;
        overflow: hidden;
    }
    
    .btn-glass::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        width: 200%;
        height: 100%;
        background: linear-gradient(115deg, 
            rgba(255, 255, 255, 0) 30%, 
            rgba(255, 255, 255, 0.3) 40%, 
            rgba(255, 255, 255, 0) 50%);
        transform: translateX(-100%);
        transition: all 0.8s ease;
    }
    
    .btn-glass:hover::before {
        transform: translateX(100%);
    }
    
    /* Animated Badge for Login Button */
    .nav-item .btn-glow::before {
        content: '';
        position: absolute;
        top: -5px;
        right: -5px;
        width: 15px;
        height: 15px;
        background: #ff4081;
        border-radius: 50%;
        animation: pulse-dot 2s cubic-bezier(0.455, 0.03, 0.515, 0.955) infinite;
        z-index: 2;
    }
    
    @keyframes pulse-dot {
        0% {
            transform: scale(0.8);
            opacity: 0.8;
        }
        50% {
            transform: scale(1);
            opacity: 1;
        }
        100% {
            transform: scale(0.8);
            opacity: 0.8;
        }
    }
    
    /* Animated Underline for Nav Links */
    .nav-link::after {
        background: linear-gradient(90deg, #45f3ff, #2196f3, #45f3ff);
        background-size: 200% auto;
        animation: gradientMove 3s linear infinite;
    }
    
    @keyframes gradientMove {
        0% {
            background-position: 0% center;
        }
        100% {
            background-position: 200% center;
        }
    }
    
    /* Floating Highlights */
    .floating-highlight {
        position: absolute;
        border-radius: 50%;
        background: radial-gradient(circle at center, rgba(69, 243, 255, 0.2) 0%, transparent 70%);
        animation: float-highlight 10s ease-in-out infinite alternate;
        z-index: 0;
    }
    
    .highlight-1 {
        width: 300px;
        height: 300px;
        top: 10%;
        right: 10%;
    }
    
    .highlight-2 {
        width: 200px;
        height: 200px;
        bottom: 20%;
        left: 10%;
        animation-delay: 2s;
    }
    
    .highlight-3 {
        width: 150px;
        height: 150px;
        top: 40%;
        left: 30%;
        animation-delay: 4s;
    }
    
    @keyframes float-highlight {
        0% {
            transform: translateY(0) scale(1);
            opacity: 0.5;
        }
        50% {
            transform: translateY(-30px) scale(1.2);
            opacity: 0.7;
        }
        100% {
            transform: translateY(0) scale(1);
            opacity: 0.5;
        }
    }
    
    /* Modern Scrollbar */
    ::-webkit-scrollbar {
        width: 8px;
    }
    
    ::-webkit-scrollbar-track {
        background: rgba(13, 19, 33, 0.8);
    }
    
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(#45f3ff, #2196f3);
        border-radius: 4px;
    }
    
    ::-webkit-scrollbar-thumb:hover {
        background: linear-gradient(#2196f3, #45f3ff);
    }
    
    /* Typed.js Text Animation */
    .typed-text-wrapper {
        display: inline-block;
        min-height: 2.5rem;
    }
    
    /* Wave Animation for Section Dividers */
    .wave-divider {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        overflow: hidden;
        line-height: 0;
        transform: rotate(180deg);
        z-index: 3;
    }
    
    .wave-divider svg {
        position: relative;
        display: block;
        width: calc(100% + 1.3px);
        height: 60px;
    }
    
    .wave-divider .shape-fill {
        fill: #FFFFFF;
    }
    
    /* Mouse Parallax Effect for Hero Content */
    .parallax-container {
        transform-style: preserve-3d;
        perspective: 1000px;
    }
    
    /* Sliced Text Effect */
    .sliced-text {
        position: relative;
        display: inline-block;
        overflow: hidden;
    }
    
    .sliced-text::after {
        content: attr(data-text);
        position: absolute;
        top: 0;
        left: 0;
        color: #45f3ff;
        clip-path: polygon(0 50%, 100% 50%, 100% 100%, 0 100%);
        transform: translateY(2px);
    }
    
    /* Improved Image Hover */
    .img-fluid {
        transition: all 0.5s ease;
        filter: saturate(0.9) brightness(0.95);
    }
    
    .img-fluid:hover {
        filter: saturate(1.1) brightness(1.05);
        transform: scale(1.02);
    }
    
    /* Selection Styling */
    ::selection {
        background: rgba(69, 243, 255, 0.3);
        color: white;
        }

    /* PREMIUM VISUAL ENHANCEMENTS */
    
    /* Elegant Glass Morphism Cards */
    .glassmorphism {
        background: rgba(255, 255, 255, 0.1);
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
        border: 1px solid rgba(255, 255, 255, 0.1);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
        border-radius: 16px;
    }
    
    /* Enhanced Hero Elements */
    .hero-section {
        background-blend-mode: luminosity;
    }
    
    /* Sophisticated Animated Background */
    .hero-animated-bg {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 0;
        opacity: 0.15;
        background: 
            linear-gradient(125deg, #2193b0, #6dd5ed),
            repeating-linear-gradient(45deg, rgba(69, 243, 255, 0.1) 0px, rgba(69, 243, 255, 0.1) 2px, transparent 2px, transparent 10px);
        background-blend-mode: overlay;
        animation: bg-shift 15s ease infinite alternate;
    }
    
    @keyframes bg-shift {
        0% {
            background-position: 0% 0%, 0% 0%;
        }
        100% {
            background-position: 100% 100%, 10% 10%;
        }
    }
    
    /* Elegant Service Card Design */
    .card {
        overflow: visible;
        border-radius: 20px;
        border: none;
    }
    
    .premium-card {
        background: linear-gradient(145deg, #fafbfc, #e8ecef);
        box-shadow: 
            5px 5px 10px rgba(0, 0, 0, 0.03),
            -5px -5px 10px rgba(255, 255, 255, 0.7);
        transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }
    
    .premium-card:hover {
        transform: translateY(-15px) scale(1.03);
        box-shadow: 
            8px 8px 20px rgba(0, 0, 0, 0.1),
            -8px -8px 20px rgba(255, 255, 255, 0.9);
    }
    
    .premium-card .service-icon {
        background: linear-gradient(135deg, #f5f7fa, #c3cfe2);
        box-shadow: 
            inset 4px 4px 8px rgba(255, 255, 255, 0.8),
            inset -4px -4px 8px rgba(0, 0, 0, 0.05);
    }
    
    .premium-card:hover .service-icon {
        background: linear-gradient(135deg, #45f3ff, #2196f3);
    }
    
    /* Elegant Animated Gradient Button */
    .btn-premium {
        position: relative;
        display: inline-block;
        padding: 12px 36px;
        margin: 10px 0;
