        font-size: 0.95rem;
        margin-bottom: 0.5rem;
        color: #546e7a;
    }
    
    /* Floating Icons Animation */
    .floating-icons {
        position: absolute;
        z-index: 2;
        opacity: 0.6;
        animation: floating 6s ease-in-out infinite;
    }
    
    .icon-1 {
        top: 20%;
        left: 10%;
        animation-delay: 0s;
    }
    
    .icon-2 {
        top: 60%;
        right: 10%;
        animation-delay: 1s;
    }
    
    .icon-3 {
        bottom: 20%;
        left: 15%;
        animation-delay: 2s;
    }
    
    @keyframes floating {
        0%, 100% {
            transform: translateY(0) rotate(0deg);
        }
        50% {
            transform: translateY(-20px) rotate(5deg);
        }
    }
    
    /* Decorative Elements */
    .decorative-circle {
        position: absolute;
        border-radius: 50%;
        border: 2px solid rgba(69, 243, 255, 0.2);
        box-shadow: 0 0 30px rgba(69, 243, 255, 0.1);
    }
    
    .circle-1 {
        width: 200px;
        height: 200px;
        top: 10%;
        right: 5%;
        border-width: 4px;
        animation: pulse-circle 4s ease infinite;
    }
    
    .circle-2 {
        width: 300px;
        height: 300px;
        bottom: 10%;
        left: 5%;
        border-width: 2px;
        animation: pulse-circle 4s ease infinite 2s;
    }
    
    @keyframes pulse-circle {
        0%, 100% {
            transform: scale(1);
            opacity: 0.5;
        }
        50% {
            transform: scale(1.05);
            opacity: 0.7;
        }
    }
    
    /* Beautiful Text Highlight Hover Effect */
    .highlight-hover {
        position: relative;
        display: inline-block;
    }
    
    .highlight-hover::after {
        content: '';
        position: absolute;
        left: 0;
        bottom: 0;
        width: 100%;
        height: 30%;
        background-color: rgba(69, 243, 255, 0.3);
        z-index: -1;
        transform: scaleX(0);
        transform-origin: bottom right;
        transition: transform 0.5s cubic-bezier(0.86, 0, 0.07, 1);
    }
    
    .highlight-hover:hover::after {
        transform: scaleX(1);
        transform-origin: bottom left;
    }
    
    /* Beautiful Background Overlay */
    .gradient-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: linear-gradient(120deg, rgba(69, 243, 255, 0.2) 0%, rgba(33, 150, 243, 0.2) 100%);
