    /* Core styles reset */
    html, body {
        margin: 0 !important;
        padding: 0 !important;
        min-height: 100vh;
        width: 100%;
        overflow-x: hidden;
        font-family: 'Poppins', sans-serif;
        color: #333;
        scroll-behavior: smooth;
        box-sizing: border-box;
    }
    
    *, *::before, *::after {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
    }
    
    /* Fix for the container-fluid */
    .container-fluid {
        padding-left: 0 !important;
        padding-right: 0 !important;
        max-width: 100% !important;
        width: 100vw !important;
        overflow-x: hidden !important;
    }
    
    /* Fix for row gutters */
    .row.g-0 {
        margin-left: 0 !important;
        margin-right: 0 !important;
    }
    
    /* Improved Navbar Styling */
    .navbar {
        transition: all 0.5s ease;
        padding: 20px 0;
        background: linear-gradient(-45deg, rgba(13, 19, 33, 0.9), rgba(33, 45, 80, 0.9), rgba(15, 40, 70, 0.9));
        background-size: 400% 400%;
        animation: gradientBG 15s ease infinite;
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
        border-bottom: 1px solid rgba(69, 243, 255, 0.1);
        box-shadow: 0 4px 30px rgba(0, 0, 0, 0.2);
        width: 100%;
        z-index: 1000;
        margin: 0 !important;
        position: absolute;
        top: 0;
        left: 0;
    }
    
    @keyframes gradientBG {
        0% {
            background-position: 0% 50%;
        }
        50% {
            background-position: 100% 50%;
        }
        100% {
            background-position: 0% 50%;
        }
    }
    
    .navbar.scrolled {
        background: rgba(13, 19, 33, 0.95) !important;
        box-shadow: 0 5px 20px rgba(0, 0, 0, 0.3);
        padding: 12px 0;
    }
    
    .navbar-brand {
        font-weight: bold;
        font-size: 1.8rem;
        display: flex;
        align-items: center;
        gap: 12px;
        margin-left: 15px;
    }
    
    .navbar .nav-link {
        font-weight: 500;
        padding: 0.5rem 1.2rem !important;
        transition: all 0.3s ease;
        margin: 0 5px;
        position: relative;
        color: rgba(255, 255, 255, 0.9) !important;
        font-size: 1.05rem;
        letter-spacing: 0.5px;
    }
    
    .navbar-nav {
        margin-right: 15px;
    }
    
    .btn-glow {
        background: linear-gradient(45deg, #45f3ff, #2196f3);
        border: 1px solid rgba(69, 243, 255, 0.3);
        color: #fff !important;
        font-weight: 600;
        padding: 10px 25px;
        border-radius: 30px;
        letter-spacing: 1px;
        position: relative;
        overflow: hidden;
        z-index: 1;
        box-shadow: 0 5px 15px rgba(33, 150, 243, 0.4);
        transition: all 0.5s ease;
    }
    
    .btn-glow::after {
        content: '';
        position: absolute;
        top: -3px;
        left: -3px;
        right: -3px;
        bottom: -3px;
        border-radius: 30px;
        background: linear-gradient(45deg, #45f3ff, #2196f3, #45f3ff);
        z-index: -1;
        animation: glowingBorder 2s linear infinite;
        opacity: 0;
        transition: opacity 0.3s ease;
    }
    
    .btn-glow:hover {
        box-shadow: 0 8px 25px rgba(33, 150, 243, 0.6);
        transform: translateY(-3px);
        color: #fff !important;
    }
    
    .btn-glow:hover::after {
        opacity: 1;
    }
    
    @keyframes glowingBorder {
        0% {
            opacity: 0.5;
            transform: scale(1);
        }
        50% {
            opacity: 0.7;
            transform: scale(1.03);
        }
        100% {
            opacity: 0.5;
            transform: scale(1);
        }
    }

    /* Enhanced Hero Section */
    .hero-section {
