    .brand-name {
        font-size: 5rem;
        letter-spacing: 5px;
        background: linear-gradient(45deg, #45f3ff, #2196f3, #45f3ff);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        animation: gradient-shift 8s ease infinite;
        background-size: 200% 200%;
