        text-shadow: 0 1px 0 rgba(255, 255, 255, 0.1),
                     0 2px 0 rgba(255, 255, 255, 0.05),
                     0 4px 6px rgba(0, 0, 0, 0.3);
        transform-style: preserve-3d;
            transition: all 0.3s ease;
