    }
    
    @keyframes pulse {
        0% {
            transform: scale(1);
        }
        50% {
            transform: scale(1.05);
        }
        100% {
            transform: scale(1);
        }
    }
    
    /* Hero Shapes */
    .hero-shapes {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 2;
        overflow: hidden;
    }
    
    .shape {
        position: absolute;
        border-radius: 50%;
        background: linear-gradient(45deg, rgba(69, 243, 255, 0.05), rgba(33, 150, 243, 0.05));
        backdrop-filter: blur(5px);
        -webkit-backdrop-filter: blur(5px);
        border: 1px solid rgba(69, 243, 255, 0.1);
    }
    
    .shape-1 {
        width: 500px;
        height: 500px;
        top: -250px;
        right: -100px;
        animation: float 15s ease-in-out infinite;
    }
    
    .shape-2 {
        width: 300px;
        height: 300px;
        bottom: -150px;
        left: -150px;
        animation: float 20s ease-in-out infinite reverse;
    }
    
    .shape-3 {
        width: 200px;
        height: 200px;
        top: 40%;
        right: 15%;
        animation: float 25s ease-in-out infinite 5s;
    }
    
    .shape-4 {
        width: 350px;
        height: 350px;
        bottom: 15%;
        right: -100px;
        animation: float 18s ease-in-out infinite 3s;
    }
    
    .shape-5 {
        width: 250px;
        height: 250px;
        top: 20%;
        left: 10%;
        animation: float 22s ease-in-out infinite 7s;
    }
    
    @keyframes float {
        0% {
            transform: translate(0, 0) rotate(0deg);
        }
        25% {
            transform: translate(15px, 15px) rotate(5deg);
        }
        50% {
            transform: translate(0, 30px) rotate(0deg);
        }
        75% {
            transform: translate(-15px, 15px) rotate(-5deg);
        }
        100% {
            transform: translate(0, 0) rotate(0deg);
        }
    }
    
    /* Scroll Indicator */
    .scroll-indicator {
        position: absolute;
        bottom: 30px;
        left: 50%;
        transform: translateX(-50%);
        z-index: 10;
            display: flex;
        flex-direction: column;
            align-items: center;
        animation: fadeInUp 2s ease 1s forwards;
        opacity: 0;
    }
    
    .mouse {
        width: 30px;
        height: 50px;
        border: 2px solid rgba(255, 255, 255, 0.8);
        border-radius: 20px;
        position: relative;
        margin-bottom: 10px;
    }
    
    .wheel {
        width: 4px;
        height: 10px;
        background: #fff;
        position: absolute;
        top: 7px;
        left: 50%;
        transform: translateX(-50%);
        border-radius: 4px;
        animation: scroll 2s ease infinite;
    }
    
    @keyframes scroll {
        0% {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
        }
        100% {
            opacity: 0;
            transform: translateX(-50%) translateY(20px);
        }
    }
    
    .scroll-text {
        color: rgba(255, 255, 255, 0.8);
        font-size: 12px;
        letter-spacing: 2px;
        text-transform: uppercase;
    }
    
    /* Media Queries for Better Responsiveness */
    @media (max-width: 992px) {
        .brand-name {
            font-size: 4rem;
        }
        
        .hero-section {
            padding-top: 100px;
