    /* Typed.js Text Animation */
    .typed-text-wrapper {
        display: inline-block;
        min-height: 2.5rem;
    }
    
    /* Wave Animation for Section Dividers */
    .wave-divider {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        overflow: hidden;
        line-height: 0;
        transform: rotate(180deg);
        z-index: 3;
    }
    
    .wave-divider svg {
        position: relative;
        display: block;
        width: calc(100% + 1.3px);
        height: 60px;
    }
    
    .wave-divider .shape-fill {
        fill: #FFFFFF;
    }
    
    /* Mouse Parallax Effect for Hero Content */
    .parallax-container {
        transform-style: preserve-3d;
        perspective: 1000px;
    }
    
    /* Sliced Text Effect */
    .sliced-text {
        position: relative;
        display: inline-block;
        overflow: hidden;
    }
    
    .sliced-text::after {
        content: attr(data-text);
        position: absolute;
        top: 0;
        left: 0;
        color: #45f3ff;
        clip-path: polygon(0 50%, 100% 50%, 100% 100%, 0 100%);
        transform: translateY(2px);
    }
    
